--
-- Name: text_to_uuid(text); Type: FUNCTION; Schema: ats; Owner: -
--

CREATE FUNCTION ats.text_to_uuid(text) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
  SELECT uuid_in(textout($1));
$_$;


--
-- Name: CAST (text AS uuid); Type: CAST; Schema: -; Owner: -
--

CREATE CAST (text AS uuid) WITH FUNCTION ats.text_to_uuid(text) AS IMPLICIT;


--
-- Name: text_eq_uuid(text, uuid); Type: FUNCTION; Schema: ats; Owner: -
--

CREATE FUNCTION ats.text_eq_uuid(text, uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT $1::uuid = $2;
$_$;


--
-- Name: uuid_eq_text(uuid, text); Type: FUNCTION; Schema: ats; Owner: -
--

CREATE FUNCTION ats.uuid_eq_text(uuid, text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT $1 = $2::uuid;
$_$;


--
-- Name: text_eq_uuid(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.text_eq_uuid(text, uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT $1::uuid = $2;
$_$;


--
-- Name: uuid_eq_text(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uuid_eq_text(uuid, text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT $1 = $2::uuid;
$_$;


--
-- Name: =; Type: OPERATOR; Schema: ats; Owner: -
--

CREATE OPERATOR ats.= (
    FUNCTION = ats.text_eq_uuid,
    LEFTARG = text,
    RIGHTARG = uuid,
    COMMUTATOR = OPERATOR(public.=)
);


--
